CREATE TABLE ai_recommendations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), signal_id uuid, model_used text NOT NULL, recommendation_type text NOT NULL, reason text NOT NULL, structured_payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY (organization_id,signal_id) REFERENCES business_signals(organization_id,id), UNIQUE(organization_id,id));
